func testBaseAccessControlRead() {
    let controller = MTRDeviceController()
    let device = MTRDevice(nodeID: n(1), controller: controller)
    let baseDevice: MTRBaseDevice = device
    _ = (device, baseDevice)
    guard let cluster = MTRBaseClusterAccessControl(device: baseDevice, endpointID: n(1), queue: DispatchQueue.global()) else {
        mtrRequire(false, "MTRBaseClusterAccessControl init")
        return
    }
    cluster.readAttributeACL(with: MTRReadParams(), completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeARL(with: MTRReadParams(), completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeAcceptedCommandList(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeAcceptedCommandList(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeAccessControlEntriesPerFabric(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeAccessControlEntriesPerFabric(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeAcl(with: MTRReadParams(), completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeAttributeList(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeAttributeList(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeClusterRevision(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeClusterRevision(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeCommissioningARL(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeExtension(with: MTRReadParams(), completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeExtension(with: MTRReadParams(), completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeFeatureMap(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeFeatureMap(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeGeneratedCommandList(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeGeneratedCommandList(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeSubjectsPerAccessControlEntry(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeSubjectsPerAccessControlEntry(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeTargetsPerAccessControlEntry(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeTargetsPerAccessControlEntry(completionHandler: { _, err in mtrExpectInvalidState(err) })
}

