func testBaseAccessControlWrite() {
    let controller = MTRDeviceController()
    let device = MTRDevice(nodeID: n(1), controller: controller)
    let baseDevice: MTRBaseDevice = device
    _ = (device, baseDevice)
    guard let cluster = MTRBaseClusterAccessControl(device: baseDevice, endpointID: n(1), queue: DispatchQueue.global()) else {
        mtrRequire(false, "MTRBaseClusterAccessControl init")
        return
    }
    cluster.writeAttributeACL(withValue: [], completion: { err in mtrExpectInvalidState(err) })
    cluster.writeAttributeACL(withValue: [], params: MTRWriteParams(), completion: { err in mtrExpectInvalidState(err) })
    cluster.writeAttributeAcl(withValue: [], completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.writeAttributeAcl(withValue: [], params: MTRWriteParams(), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.writeAttributeExtension(withValue: [], completion: { err in mtrExpectInvalidState(err) })
    cluster.writeAttributeExtension(withValue: [], completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.writeAttributeExtension(withValue: [], params: MTRWriteParams(), completion: { err in mtrExpectInvalidState(err) })
    cluster.writeAttributeExtension(withValue: [], params: MTRWriteParams(), completionHandler: { err in mtrExpectInvalidState(err) })
}
